"""Editable annotations around credited, unmodified Microsoft UI screenshots."""

def step(number, title, text=''):
    return f'<div class="vs-step"><b class="vs-number">{number}</b><div><strong>{title}</strong>{f"<span>{text}</span>" if text else ""}</div></div>'

def shot(file, alt, caption='', cls='', pins=''):
    return f'<figure class="vs-shot {cls}"><div class="vs-shot-window"><img src="assets/{file}" alt="{alt}">{pins}</div><figcaption>{caption}</figcaption></figure>'

def vscode_visual(name):
    if name == 'install':
        return '''<div class="vs-prerequisite">First: <a href="https://code.visualstudio.com/docs/setup/setup-overview" target="_blank">download and open VS Code</a> on your laptop.</div>'''+ '<div class="vs-step-row">'+step(1,'Open Extensions','Left sidebar, or Cmd/Ctrl+Shift+X')+step(2,'Search Remote - SSH','Choose the Microsoft extension')+step(3,'Click Install','Wait for installation to finish')+'</div>'+shot('vscode-remote-extension.png','Official Remote - SSH extension card showing Microsoft and the Install button','Microsoft’s example screenshot uses an older version; install the current extension.','vs-install', '<span class="vs-pin" style="left:31%;top:34%">2</span><span class="vs-pin" style="left:27%;top:72%">3</span>')+'<p class="callout">The editor and Remote - SSH extension are installed on your laptop.</p>'
    if name == 'connect':
        return '<div class="vs-connect-grid"><div>'+step(1,'Choose Connect to Host…','Cmd+Shift+P (Mac) · Ctrl+Shift+P (Windows/Linux)<br>Search: Remote-SSH: Connect to Host')+shot('vscode-connect-command.png','Microsoft remote command menu with Connect to Host selected','Microsoft menu example · focused view','vs-connect-menu')+step(2,'Enter your login address')+shot('vscode-host.png','Microsoft example of the SSH login address field','','vs-host')+'</div><div class="vs-connect-check"><div class="vs-address"><span>Use this address:</span><code>YOUR_NETID@<br>cc-login.campuscluster.illinois.edu</code></div><p>Password + Duo<br>Choose <strong>Linux</strong> if asked.</p>'+step(3,'Check the SSH indicator','Lower-left corner of the new window')+shot('vscode-statusbar.png','Official example of the green SSH status indicator','Microsoft’s example host is shown here.<br>Your indicator should name the cluster.','vs-status')+'</div></div>'
    if name == 'folder':
        return '<div class="vs-folder-grid"><div>'+step(1,'File → Open Folder','In the connected VS Code window')+shot('vscode-remote-folder.png','Official remote Open Folder dialog with a path field and OK button','Microsoft’s sample path is /home/sana/demo.<br>Replace it with your own approved project path.','vs-folder', '<span class="vs-pin" style="left:49%;top:9%">2</span>')+'</div><div class="vs-folder-check">'+step(2,'Enter the destination, then OK','Use your group’s full path, for example:')+'<div class="vs-path">/projects/YOUR_GROUP</div>'+step(3,'Confirm this window is remote','The lower-left SSH indicator names the cluster.')+shot('vscode-statusbar.png','Microsoft example SSH indicator','','vs-status')+'<p class="vs-next">Explorer now shows the remote destination.<br>The demo folder is still on your laptop.</p></div></div>'
    if name == 'upload':
        return '<div class="vs-illustration-label">Illustration · small project upload</div><div class="vs-transfer" role="img" aria-label="Drag the demo folder from the laptop into the remote Explorer. After copying, open demo and check samples.csv."><div class="vs-device"><div class="vs-device-title">Your laptop</div><div class="vs-device-content">'+step(1,'Unzip the offline package')+'<div class="vs-tree">▾ HPC_Introduction<br><span class="vs-folder-item">▸ demo</span></div><p>Find this folder in<br>Finder / File Explorer.</p></div></div><div class="vs-transfer-arrow"><strong>Drag demo</strong><span>→</span><small>into the<br>Explorer file list</small></div><div class="vs-device vs-remote-device"><div class="vs-device-title">VS Code · remote Explorer</div><div class="vs-device-content"><div class="vs-tree"><span class="vs-tree-caption">/projects/YOUR_GROUP</span><div class="vs-drop-zone">▾ demo<br>&nbsp; ▾ data<br>&nbsp; &nbsp; samples.csv<br>&nbsp; analysis.py<br>&nbsp; hello.sbatch</div></div></div><div class="vs-status-illustration">SSH: cluster login host</div></div></div><div class="vs-step-row vs-upload-bottom">'+step(2,'After upload: open demo','File → Open Folder → /projects/YOUR_GROUP/demo')+step(3,'Open data/samples.csv','Check the header and three sample rows.')+'</div>'
    if name == 'terminal':
        return step(1,'Terminal → New Terminal','In your remote VS Code window')+shot('vscode-remote-terminal.png','Official VS Code remote bash terminal showing uname followed by Linux','Microsoft’s remote terminal example. Run our three checks below in your own project.','vs-terminal')+'''<div class="vs-terminal-checks"><div><code>hostname</code><span>Which computer?<br>Expect a login node.</span></div><div><code>cd /projects/YOUR_GROUP/demo</code><span>Move into your uploaded project.<br>Use your group’s actual path.</span></div><div><code>pwd</code><span>Which folder?<br>Check the full project path.</span></div></div><p class="callout">Run one line, press Enter, wait for the prompt, then continue.</p>'''
    if name == 'result':
        return '''<div class="vs-illustration-label">Illustration · expected result from the supplied demo</div><div class="vs-result-window" role="img" aria-label="Explorer contains results/summary.csv. Its editor shows samples,total_reads followed by 3,3700."><div class="vs-result-explorer"><div class="vs-tree-caption">EXPLORER · DEMO</div><div class="vs-tree">▸ data<br><span class="vs-result-folder"><b class="vs-number">1</b> ▾ results</span><span class="vs-result-selected"><b class="vs-number">2</b> summary.csv</span>analysis.py<br>analysis.sbatch</div></div><div class="vs-result-editor"><div class="vs-result-tab">summary.csv</div><div class="vs-csv"><span>1</span><code>samples,total_reads</code><span>2</span><code>3,3700</code></div><div class="vs-result-check"><b class="vs-number">3</b><p>3 input samples<br>3,700 total reads</p></div></div></div><div class="vs-result-bottom"><p><strong>Read it here.</strong> No download needed.<br>For a local copy: right-click the remote file → <strong>Download…</strong></p><p><strong>Other viewers:</strong> logs and images open directly;<br>Rainbow CSV colors columns; PDF/Jupyter extensions open those files.</p></div>'''
    raise ValueError(name)
